INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Josh Powlison''s Button: Mildly Remastered Edition', 'Press a button. Increment a number. Change reality. The instant classic returns for a mildly remastered electric boogaloo on modern computer systems. Once again experience the euphoria of button pressing with Josh Powlison''s striking developer commentary to guide you.' FROM games WHERE igdb_id = 303596 ON CONFLICT (game_id, language_code) DO NOTHING;
