INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('remute-dreammachine', 321802, '2024-10-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co90z1.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Remute: Dreammachine', 'After highly acclaimed and unique game console albums for SNES, Mega Drive, Jaguar, N64, Gameboy or even 3DO, the German electronic music producer Remute presents his most ambitious work to date: Together with his long-standing cooperator and amazing graphic artist Alien^PDX he created Dreammachine - a full CGI feature film inviting you to a deep dream journey filled to the brim with psychedelic sequences, epic animations and a strangely meditative ambient soundtrack.' FROM games WHERE igdb_id = 321802 ON CONFLICT (game_id, language_code) DO NOTHING;
