INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Remute: There Is Hope', 'Within only five years Remute became the trailblazer for game cartridge based music albums delivering releases for consoles like Super Nintendo, Gameboy, Sega Genesis, Nintendo 64 and many more. In 2024 he is increasing the niche force even further and surprises us with the very first music album for Atari’s ill-fated, but immensly powerful Jaguar – the first 64-bit gameconsole ever released back in 1993.' FROM games WHERE igdb_id = 321800 ON CONFLICT (game_id, language_code) DO NOTHING;
