INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outlanders 2: Second Nature', 'Welcome back to the Outlands! A new, courageous generation of outlanders is ready to redefine life on the Outlands, with new aproaches to building and surviving, uncharted heights and horizons, and an ecosystem more vibrant than ever before.
