INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blasphemous 2: Limited Collector''s Edition', 'This Physical Edition includes a Steelbook case with exclusive artwork, a printed instruction manual created by the developers along with a thank you letter from the Game Kitchen team, a Marca del Martitio metal coin, three art cards with new illustrations, two CD’s of music composed by Carlos Viola along with a collector’s CD cover with code to download the digital soundtrack, a printed game guide with over 60 pages of Blasphemous lore a beautiful album of illustrations and a certificate of authenticity all housed in a specially created premium finish collector’s box.' FROM games WHERE igdb_id = 281293 ON CONFLICT (game_id, language_code) DO NOTHING;
