INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saga of Song', 'Saga of Song is a fast-paced single-screen Platformer and a continuation of the Legend of Song. The game is filled with Imagination, complete with competitive online hi-scores and controller support, and fraught with plenty of flavor and danger for you to enjoy! Each randomly generated game consists of 9 Stages which contain treasure and stars to collect in order to maintain the Song and (completely) clear (3x) in order to progress.' FROM games WHERE igdb_id = 287342 ON CONFLICT (game_id, language_code) DO NOTHING;
