INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Polynya', 'Polynya is an atmospheric quiet walking simulator about taking a walk around a frozen lake with your little kid on a sled. Leave your trace in the deep snow or just lay down and stare into the sky. Maybe something or somebody can be found there behind the snow covered pines. Maybe something awaits in the dark water.' FROM games WHERE igdb_id = 306767 ON CONFLICT (game_id, language_code) DO NOTHING;
