INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chopper Strike', 'Chopper Strike is an arcade-style aerial combat game where you pilot a powerful attack helicopter through six diverse environments, from urban warzones to icy tundras, completing mission objectives like convoy defense, armoured-target elimination, and stronghold destruction. Use an expanding arsenal of rockets and weapons to create massive explosions and tear through destructible environments, with each mission unlocking more powerful ordnance.' FROM games WHERE igdb_id = 304794 ON CONFLICT (game_id, language_code) DO NOTHING;
