INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Songs of the Hmong', 'The culture of Chinese Hmong nationality boasts pluralistic artistry, and it has its own uniqueness in construction, literature, painting, patterns, craft, etc. However their ways of inherit the knowledge is limited due to the absence of written language. In present days, the younger generation is showing a huge passion about video games, thus demonstrating a possibility for young people to grow interest on these fading traditional cultures by binding them with the Ninth Art.' FROM games WHERE igdb_id = 250243 ON CONFLICT (game_id, language_code) DO NOTHING;
