INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Freaks Arcade', 'Super Freaks Arcade is a throwback to single-screen arcade games, loosely based on a combination of Mario Bros., and Pac-Man Championship Edition. It aims to reinterpret the gameplay of Super Freaks 1 Ultimate Edition as if it were a 1983 arcade game. While it was originally made in two weeks for the Freakjam 1 pack, Super Freaks Arcade is receiving content updates and overhauls over time that will continue to expand it.' FROM games WHERE igdb_id = 316544 ON CONFLICT (game_id, language_code) DO NOTHING;
