INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmare Flight', 'Nightmare Flight is a horror game that takes place in an airplane. Survive through three different horror scenarios, while trying to fly an airplane without a co-pilot. You must check on the passengers, and noises from the plane, but do not leave the cockpit for too long. The Undead, Aliens, and different creatures have boarded the plane. They will try to grab, attack, and drag you to your death. Fly the plane, while fighting off these monsters to survive the flight.' FROM games WHERE igdb_id = 322883 ON CONFLICT (game_id, language_code) DO NOTHING;
