INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World War: An Age of Industry & Magic', 'A collectible card game with a setting that draws from historical elements of the late 19th and early 20th centuries such as Spiritualism, the Victorian Era, the Industrial Revolution, psuedo-science and quackery of the time like Galvanism, both World Wars, and the sentiment of fin de siècle.' FROM games WHERE igdb_id = 282195 ON CONFLICT (game_id, language_code) DO NOTHING;
