INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dough: A Crime Strategy RPG', 'Money, power, women, status... in the Prohibition, the world of crime is prospering. A Strategy RPG game where you start from the bottom and try to conquer the whole city, it would''ve been so easy too if you didn''t have to fight pesky policemen, greedy politicians and ruthless competition.' FROM games WHERE igdb_id = 264645 ON CONFLICT (game_id, language_code) DO NOTHING;
