INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toy Titan: Protector of Childhood Dreams', 'In a faraway realm, the benevolent Eldritch Crafters have entrusted you with a powerful artifact: the Dreamcore. This enchanted relic safeguards the vibrant fantasies and imaginations of children across the globe. However, the world is threatened by the malevolent sorcerer, Nythros, who desires to shatter the Dreamcore and plunge everything into a bleak, dreamless void.' FROM games WHERE igdb_id = 325775 ON CONFLICT (game_id, language_code) DO NOTHING;
