INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drift Master Simulator', 'Prepare to dominate the drift scene in Drift Master Simulator! Embark on your journey as a street drifter, where you''ll begin by selecting your first car from iconic options in the USA, Japan, or Germany. With hard work, dedication, and skillful drifting, ascend through the ranks to claim your place as a top drifter. Feel the adrenaline as you master the art of controlled slides and perfect your technique on challenging tracks.' FROM games WHERE igdb_id = 315922 ON CONFLICT (game_id, language_code) DO NOTHING;
